     3	export type Resource<T> =
     4	  | { status: 'idle' }
     5	  | { status: 'loading' }
     6	  | { status: 'ready'; data: T }
     7	  | { status: 'error'; error: unknown }
     8	
     9	/**
    10	 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
    11	 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
    12	 * because every settled value is tagged with the request token that produced it.
    13	 * `refreshToken` forces a reload without changing the key (the header Refresh button).
    14	 */
    15	export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0): { state: Resource<T>; reload: () => void } {
    16	  const [settled, setSettled] = useState<{ token: string; value: Resource<T> } | null>(null)
    17	  const [attempt, setAttempt] = useState(0)
    18	  const loadRef = useRef(load)
    19	  useEffect(() => { loadRef.current = load }, [load])
    20	  const token = key === null ? null : `${key}\u0000${attempt}\u0000${refreshToken}`
    21	
    22	  useEffect(() => {
    23	    if (token === null) return
    24	    const controller = new AbortController()
    25	    loadRef.current(controller.signal).then(
    26	      data => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'ready', data } }) },
    27	      error => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'error', error } }) },
    28	    )
    29	    return () => controller.abort()
    30	  }, [token])
    31	
    32	  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
    33	  const state: Resource<T> = token === null ? { status: 'idle' } : settled?.token === token ? settled.value : { status: 'loading' }
    34	  return { state, reload }
    35	}
    36	/**
    37	 * Projects routes: `/projects[/<project>[/workflows/<workflow>[/runs/<run>[/nodes/<node>]]]]`.
    38	 *
    39	 * Every ID is an opaque contract identifier: it must match the shared ID pattern and is percent-encoded
    40	 * as one path segment. Anything else is malformed rather than looked up. This domain is read-only and
    41	 * separate from the Pi/Claude skill sources; nothing here names a filesystem path.
    42	 */
    43	
    44	/** Same pattern as the shared projects contract (`contracts/projects/v1.ts`). */
    45	export const PROJECT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/
    46	
    47	export const PROJECTS_ROUTE = 'projects'
    48	
    49	export type ProjectsRoute =
    50	  | { level: 'projects' }
    51	  | { level: 'project'; projectId: string }
    52	  | { level: 'workflow'; projectId: string; workflowId: string }
    53	  | { level: 'run'; projectId: string; workflowId: string; runId: string; nodeId: string | null }
    54	
    55	export function isContractId(value: string): boolean {
    56	  return PROJECT_ID_PATTERN.test(value)
    57	}
    58	
    59	function encode(segments: string[]): string {
    60	  return `/${segments.map(encodeURIComponent).join('/')}`
    61	}
    62	
    63	export function projectsPathname(): string {
    64	  return `/${PROJECTS_ROUTE}`
    65	}
    66	
    67	export function projectPathname(projectId: string): string {
    68	  return encode([PROJECTS_ROUTE, projectId])
    69	}
    70	
    71	export function workflowPathname(projectId: string, workflowId: string): string {
    72	  return encode([PROJECTS_ROUTE, projectId, 'workflows', workflowId])
    73	}
    74	
    75	export function runPathname(projectId: string, workflowId: string, runId: string, nodeId: string | null = null): string {
    76	  const segments = [PROJECTS_ROUTE, projectId, 'workflows', workflowId, 'runs', runId]
    77	  if (nodeId !== null) segments.push('nodes', nodeId)
    78	  return encode(segments)
    79	}
    80	
    81	export function routeToPathname(route: ProjectsRoute): string {
    82	  switch (route.level) {
    83	    case 'projects': return projectsPathname()
    84	    case 'project': return projectPathname(route.projectId)
    85	    case 'workflow': return workflowPathname(route.projectId, route.workflowId)
    86	    case 'run': return runPathname(route.projectId, route.workflowId, route.runId, route.nodeId)
    87	  }
    88	}
    89	
    90	/** Whether a pathname belongs to the Projects domain at all (decided before any decoding). */
    91	export function isProjectsPathname(pathname: string): boolean {
    92	  const first = pathname.split('/').filter(segment => segment !== '')[0]
    93	  return first === PROJECTS_ROUTE
    94	}
    95	
    96	/**
    97	 * Parses a Projects pathname. Returns null when it is not a Projects pathname or when any segment is
    98	 * malformed (bad encoding, an invalid ID, an unexpected literal or trailing segments).
    99	 */
   100	export function parseProjectsPathname(pathname: string): ProjectsRoute | null {
   101	  const raw = pathname.split('/').filter(segment => segment !== '')
   102	  if (raw[0] !== PROJECTS_ROUTE) return null
   103	  let segments: string[]
   104	  try {
   105	    segments = raw.slice(1).map(decodeURIComponent)
   106	  } catch {
   107	    return null
   108	  }
   109	  if (segments.length === 0) return { level: 'projects' }
   110	  const [projectId, workflowsLiteral, workflowId, runsLiteral, runId, nodesLiteral, nodeId, ...rest] = segments
   111	  if (!isContractId(projectId)) return null
   112	  if (workflowsLiteral === undefined) return { level: 'project', projectId }
   113	  if (workflowsLiteral !== 'workflows' || workflowId === undefined || !isContractId(workflowId)) return null
   114	  if (runsLiteral === undefined) return { level: 'workflow', projectId, workflowId }
   115	  if (runsLiteral !== 'runs' || runId === undefined || !isContractId(runId)) return null
   116	  if (nodesLiteral === undefined) return { level: 'run', projectId, workflowId, runId, nodeId: null }
   117	  if (nodesLiteral !== 'nodes' || nodeId === undefined || !isContractId(nodeId) || rest.length > 0) return null
   118	  return { level: 'run', projectId, workflowId, runId, nodeId }
   119	}
